<?php
$page_title='Edit Course'; require_once __DIR__.'/../../config/database.php'; require_once __DIR__.'/../../config/session.php'; require_once __DIR__.'/../../config/functions.php'; require_once __DIR__.'/../../config/auth.php'; requireAdmin(); $id=(int)($_GET['id']??$_POST['id']??0); $stmt=$pdo->prepare('SELECT * FROM courses WHERE id=?');$stmt->execute([$id]);$course=$stmt->fetch();if(!$course){header('Location: index.php');exit;}$mentors=$pdo->query("SELECT id,full_name FROM users WHERE role='mentor' AND is_active=1 ORDER BY full_name")->fetchAll();$fields=$pdo->query('SELECT id,name FROM academic_fields WHERE is_active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??'');$mentor=(int)($_POST['mentor_id']??0);$field=(int)($_POST['field_id']??0);$description=trim($_POST['description']??'');$level=$_POST['level']??'beginner';$price=(float)($_POST['price']??0);$duration=(int)($_POST['duration']??0);$status=$_POST['status']??'draft';if($title&&$mentor){$stmt=$pdo->prepare('UPDATE courses SET mentor_id=?,field_id=?,title=?,slug=?,description=?,price=?,level=?,duration=?,status=?,featured=? WHERE id=?');$stmt->execute([$mentor,$field?:null,$title,createSlug($title).'-'.$id,$description,$price,$level,$duration,$status,isset($_POST['featured'])?1:0,$id]);header('Location: index.php');exit;}}
?>
<?php include __DIR__.'/../includes/header.php'; ?><div class="admin-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><main class="admin-main"><div class="admin-topbar"><div><h1 class="admin-title">Edit course</h1><p class="admin-subtitle">Update catalogue details and publishing state.</p></div><a class="btn btn-outline-secondary" href="index.php">Back</a></div><div class="admin-card"><form method="POST"><input type="hidden" name="id" value="<?php echo $id; ?>"><div class="admin-form-grid"><div class="full"><label>Title</label><input name="title" required value="<?php echo htmlspecialchars($course['title']); ?>"></div><div><label>Mentor</label><select name="mentor_id" required><?php foreach($mentors as $mentor): ?><option value="<?php echo $mentor['id']; ?>" <?php echo $course['mentor_id']==$mentor['id']?'selected':''; ?>><?php echo htmlspecialchars($mentor['full_name']); ?></option><?php endforeach; ?></select></div><div><label>Academic field</label><select name="field_id"><option value="">General</option><?php foreach($fields as $field): ?><option value="<?php echo $field['id']; ?>" <?php echo $course['field_id']==$field['id']?'selected':''; ?>><?php echo htmlspecialchars($field['name']); ?></option><?php endforeach; ?></select></div><div><label>Level</label><select name="level"><?php foreach(['beginner','intermediate','advanced'] as $level): ?><option <?php echo $course['level']===$level?'selected':''; ?>><?php echo $level; ?></option><?php endforeach; ?></select></div><div><label>Status</label><select name="status"><?php foreach(['draft','pending','active','inactive','archived'] as $status): ?><option value="<?php echo $status; ?>" <?php echo $course['status']===$status?'selected':''; ?>><?php echo ucfirst($status); ?></option><?php endforeach; ?></select></div><div><label>Price</label><input type="number" step="0.01" min="0" name="price" value="<?php echo $course['price']; ?>"></div><div><label>Duration (hours)</label><input type="number" min="0" name="duration" value="<?php echo $course['duration']; ?>"></div><div class="full"><label>Description</label><textarea name="description"><?php echo htmlspecialchars($course['description']??''); ?></textarea></div><div><label><input type="checkbox" name="featured" <?php echo $course['featured']?'checked':''; ?>> Featured course</label></div></div><button class="btn btn-primary mt-3"><i class="fas fa-save"></i> Save changes</button></form></div></main></div><?php include __DIR__.'/../includes/footer.php'; ?>
